cd $TMPDIR/run && cp -r $TMPDIR/out/contract ./c && echo '{"type":"module","dependencies":{"@midnight-ntwrk/compact-runtime":"0.21.0"}}' > package.json && cat > t.mjs <<'EOF'
import * as rt from '@midnight-ntwrk/compact-runtime';
import { Contract, ledger } from './c/index.js';
const sk = n => new Uint8Array(32).fill(n);
let cur = sk(1);
const w = { secretKey: (ctx) => [ctx.privateState, cur] };
const c = new Contract(w);
const pk = n => c.circuits.publicKey ? c.pureCircuits.publicKey(sk(n)) : null;
const A = pk(1), B = pk(2);
const coinPk = '0'.repeat(64);
let r = c.initialState(rt.createConstructorContext({}, coinPk));
let ctx = rt.createCircuitContext(rt.dummyContractAddress(), coinPk, r.currentContractState, r.currentZswapLocalState);
const show = (l) => { const s = ledger(ctx.currentQueryContext.state); console.log(l, 'supply=', s.totalSupply, [...s.balances].map(([k,v])=>[Buffer.from(k).toString('hex').slice(0,6),v])); };
const call = (l, f) => { try { ctx = f().context; show(l);} catch(e){ console.log(l,'FAILED:',e.message);} };
show('init');
cur=sk(2); call('mint by non-admin', ()=>c.circuits.mint(ctx,A,100n));
cur=sk(1);
call('mint 100->A', ()=>c.circuits.mint(ctx,A,100n));
call('transfer 30 A->B', ()=>c.circuits.transfer(ctx,B,30n));
call('transfer 500 A->B', ()=>c.circuits.transfer(ctx,B,500n));
call('self transfer 10', ()=>c.circuits.transfer(ctx,A,10n));
call('burn 20 by A', ()=>c.circuits.burn(ctx,20n));
call('burn 999 by A', ()=>c.circuits.burn(ctx,999n));
console.log('balanceOf A', c.circuits.balanceOf(ctx,A).result, 'B', c.circuits.balanceOf(ctx,B).result, 'none', c.circuits.balanceOf(ctx,sk(9)).result);
EOF
node t.mjs 2>&1 | head -30

