import * as rt from '@midnight-ntwrk/compact-runtime';
import { Contract, ledger, pureCircuits } from './c/index.js';
const sk = n => new Uint8Array(32).fill(n);
let cur = sk(1);
const c = new Contract({ secretKey: (ctx) => [ctx.privateState, cur] });
const A = pureCircuits.publicKey(sk(1)), B = pureCircuits.publicKey(sk(2));
const coinPk = '0'.repeat(64), addr = rt.dummyContractAddress();
const r = await c.initialState(rt.createConstructorContext({}, coinPk));
let state = r.currentContractState;
const mk = (id) => rt.createCircuitContext({circuitId:id, contractAddress:addr, coinPublicKeyOrZswapState:coinPk, contractState:state, privateState:{}});
const show = (l) => { const s = ledger(state); console.log(l.padEnd(22), 'supply=', s.totalSupply, [...s.balances].map(([k,v])=>Buffer.from(k).toString('hex').slice(0,4)+':'+v).join(' ')); };
